import type { Schema, Template } from "sanity";
import type { TranslationsConfig } from "./config";

/**
 * Keeps only the initial-value templates for the current Studio language on translatable types
 * (as generated by @sanity/document-internationalization, e.g. `article-en`), and drops the
 * default language-less template (`article`).
 *
 * @public
 */
export function filterTemplatesByStudioLanguage(config: TranslationsConfig, templates: Template[], schema: Schema): Template[] {
  const language = config.getStudioLanguage();

  return templates.filter((template) => {
    if (!config.isTranslatable(template.schemaType, schema)) {
      return true;
    }

    if (template.id === template.schemaType) {
      return false;
    }

    const value = typeof template.value === "object" && template.value !== null ? (template.value as Record<string, unknown>) : undefined;

    // Function-valued templates (e.g. child templates) can't be inspected here, keep them.
    return value ? value[config.languageField] === language : true;
  });
}
